head.script:
scwin.idCount = -1;
scwin.createDataList = function() {
	var infoArr = [
		{ "id": "column1", "dataType": "text", "name": "name1" },
		{ "id": "column2", "dataType": "text", "name": "name2" }
	];
	for (var i = 2; i <= 5; i++) {
		$p.data.create({
			"id": "dataList" + i,
			"type": "dataList",
			"option": {
				"baseNode": "map"
			},
			"columnInfo": infoArr
		});
	}
};
scwin.trigger1_onclick = function(e) {
	scwin.createDataList();
};
scwin.trigger2_onclick = function(e) {
	for (var i = 0; i < 200; i++) {
		scwin.createDataList();
	}
};
scwin.trigger3_onclick = function(e) {
	scwin.idCount = Object.keys(WebSquare.idCache).length;
};
scwin.trigger4_onclick = function(e) {
	$p.data.remove("dataList2");
	$p.data.remove("dataList3");
	$p.data.remove("dataList4");
	$p.data.remove("dataList5");
};
